import{_ as t,o as s,c as o,a5 as r}from"./chunks/framework.CslsFoWx.js";const m=JSON.parse('{"title":"Serveur MCP Vendora — besoin, expérience et plan (M0, M1, M3, M2 et U1 faits ; la suite planifiée)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/mcp-vendora.md","filePath":"generated/architecture/mcp-vendora.md","lastUpdated":null}'),a={name:"architecture/mcp-vendora.md"};function n(i,e,d,c,l,u){return s(),o("div",null,[...e[0]||(e[0]=[r('<div><h1 id="serveur-mcp-vendora-—-besoin-experience-et-plan-m0-m1-m3-m2-et-u1-faits-la-suite-planifiee" tabindex="-1">Serveur MCP Vendora — besoin, expérience et plan (M0, M1, M3, M2 et U1 faits ; la suite planifiée) <a class="header-anchor" href="#serveur-mcp-vendora-—-besoin-experience-et-plan-m0-m1-m3-m2-et-u1-faits-la-suite-planifiee" aria-label="Permalink to &quot;Serveur MCP Vendora — besoin, expérience et plan (M0, M1, M3, M2 et U1 faits ; la suite planifiée)&quot;">​</a></h1><blockquote><p><strong>Statut au 11/11/2026 : prérequis serveur (M0), serveur MCP en lecture seule (M1) et jeu de questions de référence (U1) faits et testés ; le serveur MCP est en ligne sur le staging (<code>https://vendora-mcp-staging.onrender.com/mcp</code>, clé « Assistant IA »), rien en production.</strong> La connexion OAuth (M3) est faite et prouvée en local (branche <code>mcp-m3</code>) ; sa preuve réelle depuis Claude sur le staging reste à faire par Ahmed. La page « Assistant IA » (M2) est fusionnée depuis le 12/11 ; restent l&#39;hébergement sans veille (avec la production), puis U2 → U6 et M4 — détail et restes au § 8. Règles : <a href="/VendoraSystem-docs/specs/18-mcp">spec 18</a>. Ce document décrit <strong>à qui ça sert, ce qu&#39;on peut demander, comment on s&#39;en sert</strong>, puis l&#39;architecture et les lots. Mode d&#39;emploi côté commerçant : <a href="/VendoraSystem-docs/architecture/mcp-guide">guide d&#39;utilisation (brouillon)</a>. Code et exploitation : <a href="./../mcp/README"><code>mcp/README.md</code></a> ; jeu de questions : <a href="./../mcp/evals/README"><code>mcp/evals/README.md</code></a>. Suivi : <a href="/VendoraSystem-docs/suivi/journal">TRACKING › MCP Vendora</a> et cartes « MCP » du tableau Trello (M0 → M4, U1 → U6).</p></blockquote><h2 id="_1-en-une-phrase" tabindex="-1">1. En une phrase <a class="header-anchor" href="#_1-en-une-phrase" aria-label="Permalink to &quot;1. En une phrase&quot;">​</a></h2><p><strong>Le commerçant parle à l&#39;assistant qu&#39;il utilise déjà (Claude, ChatGPT…) et obtient des réponses justes sur son commerce</strong> — « Comment s&#39;est passée ma journée ? », « Que dois-je commander ? », « Pourquoi ma marge baisse ? » — depuis son téléphone, sans ouvrir le back-office, sans rien installer, et en pouvant couper l&#39;accès d&#39;un clic.</p><p><strong>MCP (Model Context Protocol)</strong> est le protocole ouvert qui rend cela possible : un serveur déclare des <strong>outils</strong> (nom, description, paramètres) ; l&#39;assistant décide seul quand les appeler et rédige la réponse à partir du résultat. C&#39;est aussi le lot <strong>A8</strong> de l&#39;<a href="/VendoraSystem-docs/commercial/etude-gaas">étude GaaS</a> : le même registre d&#39;outils sert nos futurs agents et l&#39;assistant du commerçant.</p><h2 id="_2-pour-qui-pour-quoi" tabindex="-1">2. Pour qui, pour quoi <a class="header-anchor" href="#_2-pour-qui-pour-quoi" aria-label="Permalink to &quot;2. Pour qui, pour quoi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Qui</th><th>Sa situation</th><th>Ce qu&#39;il attend</th><th>Où il l&#39;utilise</th></tr></thead><tbody><tr><td><strong>Gérant / propriétaire</strong> (restaurant, boulangerie, épicerie, boutique)</td><td>Le soir ou entre deux services, pas le temps d&#39;ouvrir cinq rapports</td><td>Un bilan clair, les anomalies, quoi faire demain</td><td>Application Claude ou ChatGPT <strong>sur son téléphone</strong></td></tr><tr><td><strong>Propriétaire de plusieurs magasins</strong></td><td>Veut comparer sans exporter de tableaux</td><td>Classement des magasins, celui qui décroche et pourquoi</td><td>Téléphone ou ordinateur</td></tr><tr><td><strong>Responsable des achats / chef de cuisine</strong></td><td>Commande à l&#39;instinct, ruptures et pertes</td><td>Liste de réassort par fournisseur, dérive du food cost</td><td>Ordinateur du bureau</td></tr><tr><td><strong>Comptable, contrôleur de gestion</strong></td><td>Prépare les clôtures</td><td>TVA du jour, écarts de caisse, clôtures manquantes, lien vers les exports</td><td>Ordinateur</td></tr><tr><td><strong>Intégrateur, développeur partenaire</strong></td><td>Automatise pour un client</td><td>Outils stables, clé limitée, documentation</td><td>Claude Code, scripts</td></tr></tbody></table><p><strong>Le besoin n&#39;est pas « exposer l&#39;API à une IA »</strong> : c&#39;est faire gagner du temps de lecture et de décision à quelqu&#39;un qui n&#39;est pas technique. Tout le plan en découle : connexion sans copier de clé, outils pensés par <strong>question</strong> (pas par route), chiffres calculés par Vendora (jamais par le modèle), réponses qui disent leur période et leur fraîcheur, et un lien pour aller vérifier dans le back-office.</p><h2 id="_3-ce-que-le-commercant-peut-demander-v1-lecture-seule" tabindex="-1">3. Ce que le commerçant peut demander (v1, lecture seule) <a class="header-anchor" href="#_3-ce-que-le-commercant-peut-demander-v1-lecture-seule" aria-label="Permalink to &quot;3. Ce que le commerçant peut demander (v1, lecture seule)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Priorité</th><th>Question type</th><th>Ce que Vendora renvoie</th><th>Outil</th></tr></thead><tbody><tr><td>1</td><td>« Comment s&#39;est passée ma journée / ma semaine ? »</td><td>Chiffre d&#39;affaires, nombre de tickets, ticket moyen, <strong>écart avec la période précédente équivalente</strong>, heures de pointe, moyens de paiement</td><td><code>sales_summary</code></td></tr><tr><td>1</td><td>« Qu&#39;est-ce qui marche, qu&#39;est-ce qui ne se vend plus ? »</td><td>Meilleures ventes, produits en baisse, produits dormants</td><td><code>top_products</code></td></tr><tr><td>1</td><td>« Que dois-je commander cette semaine ? »</td><td>Produits sous le seuil ou bientôt en rupture au rythme actuel, déjà en commande ou non, regroupés par fournisseur</td><td><code>reorder_suggestions</code></td></tr><tr><td>1</td><td>« Pourquoi ma marge baisse ? »</td><td>Marge par produit et par catégorie, hausses de prix d&#39;achat, dérive du food cost, poids des remises et des pertes</td><td><code>margin_analysis</code></td></tr><tr><td>2</td><td>« Ma caisse est-elle juste ? »</td><td>Sessions ouvertes, écarts de comptage, Z du jour, annulations et remises, validations du manager</td><td><code>cash_control</code></td></tr><tr><td>2</td><td>« Est-ce que tout marche en magasin ? »</td><td>Appareils hors ligne, synchronisation en retard, bornes</td><td><code>devices_health</code></td></tr><tr><td>2</td><td>« Où en sont mes achats ? »</td><td>Bons en cours, réceptions attendues, factures à échéance, soldes fournisseurs</td><td><code>purchasing_status</code></td></tr><tr><td>2</td><td>« Quel magasin décroche ? »</td><td>Comparaison des magasins sur la même période</td><td><code>compare_stores</code></td></tr><tr><td>2</td><td>« Combien vaut mon stock ? Qu&#39;est-ce qui va périmer ? »</td><td>Valeur, ruptures, pertes, lots proches de la date limite</td><td><code>stock_status</code></td></tr><tr><td>3</td><td>« Combien coûte le croissant, combien j&#39;en ai ? »</td><td>Fiche courte d&#39;un produit trouvé par son nom, même approximatif</td><td><code>find_product</code></td></tr><tr><td>3</td><td>« Comment fait-on un inventaire dans Vendora ? »</td><td>Extrait de la page d&#39;aide et son lien</td><td><code>vendora_help</code></td></tr><tr><td>option</td><td>« Y a-t-il des alertes anti-fraude ? »</td><td>Alertes ouvertes (portée sensible, à accorder exprès)</td><td><code>fraud_alerts</code></td></tr></tbody></table><p>Hors v1 : toute écriture (lot M4, par propositions validées), les données nominatives des clients et des salariés (agrégats seulement, voir § 9), le paiement, le fiscal en écriture.</p><h2 id="_4-comment-il-s-en-sert" tabindex="-1">4. Comment il s&#39;en sert <a class="header-anchor" href="#_4-comment-il-s-en-sert" aria-label="Permalink to &quot;4. Comment il s&#39;en sert&quot;">​</a></h2><p>Détail pas à pas : <a href="/VendoraSystem-docs/architecture/mcp-guide">guide d&#39;utilisation</a>. En résumé, trois parcours :</p><ol><li><strong>Commerçant, « en un clic »</strong> (parcours principal) : dans Claude ou ChatGPT, il ajoute le connecteur Vendora (une adresse <code>https://…/mcp</code>, ou plus tard l&#39;annuaire des connecteurs), <strong>se connecte avec son compte Vendora</strong>, choisit les magasins et les familles de données qu&#39;il autorise, et pose sa première question. Aucune clé à copier, fonctionne sur téléphone. Demande OAuth (lot M3).</li><li><strong>Intégrateur, développeur</strong> : il crée une clé « Assistant IA » au back-office et la donne à Claude Code ou à son script (en-tête <code>X-API-Key</code>). Disponible dès M1.</li><li><strong>Essayer sans compte</strong> : un commerce de démonstration public, pour voir ce que ça donne avant de connecter ses vraies données (lot U5).</li></ol><p>Le back-office garde la main : page <strong>Réglages › Assistant IA</strong> avec les assistants connectés, <strong>ce qu&#39;ils ont consulté</strong> en clair (« a lu les ventes du 10/11 de Petit Bistrot »), le retrait d&#39;un accès et l&#39;arrêt d&#39;urgence.</p><h2 id="_5-principes-d-experience" tabindex="-1">5. Principes d&#39;expérience <a class="header-anchor" href="#_5-principes-d-experience" aria-label="Permalink to &quot;5. Principes d&#39;expérience&quot;">​</a></h2><p>Un modèle de langage choisit les outils d&#39;après leur description et rédige d&#39;après leur résultat : <strong>la description et la forme du résultat sont l&#39;interface</strong>. Dix règles, à tenir sur chaque outil.</p><ol><li><strong>Un outil = une question du commerçant</strong>, pas une route de l&#39;API. Une douzaine d&#39;outils au plus ; un modèle choisit mal parmi cinquante.</li><li><strong>Vendora calcule, le modèle raconte.</strong> Totaux, écarts, pourcentages, classements et comparaisons arrivent déjà calculés. Le modèle ne fait jamais d&#39;addition sur une liste.</li><li><strong>Les périodes se disent en mots.</strong> Paramètre <code>period</code> (<code>today</code>, <code>yesterday</code>, <code>this_week</code>, <code>last_week</code>, <code>this_month</code>, <code>last_month</code>, <code>last_7_days</code>, <code>last_30_days</code>, ou <code>from</code> / <code>to</code>) résolu <strong>dans le fuseau du magasin</strong>. La réponse rappelle la période retenue (« du lundi 2 au dimanche 8 novembre »).</li><li><strong>Les noms suffisent.</strong> Magasin et produit acceptés par leur nom, même approximatif ; s&#39;il y a doute, l&#39;outil renvoie les candidats au lieu de deviner. Un seul magasin : le paramètre est facultatif.</li><li><strong>Chaque montant est prêt à citer</strong> : unités mineures, devise <strong>et</strong> texte formaté selon la langue du commerce (« 1 234,50 € »).</li><li><strong>Chaque réponse dit sa fraîcheur</strong> : <code>dataFreshAt</code> ; au-delà de 15 minutes, ou si une caisse n&#39;a pas synchronisé, un avertissement explicite que l&#39;assistant doit répéter.</li><li><strong>Court par défaut</strong> : dix lignes au plus, un résumé en une phrase (<code>summary</code>), le détail sur demande (<code>limit</code>, <code>detail</code>). Les réponses longues coûtent cher et noient le modèle.</li><li><strong>Une suite à chaque réponse</strong> : lien direct vers l&#39;écran du back-office qui montre le même chiffre, et une ou deux questions de suite suggérées.</li><li><strong>Des erreurs qui disent quoi faire</strong>, en clair : « Cet accès ne couvre pas le magasin Lac 2 ; magasins autorisés : Centre, Marsa. Le propriétaire peut l&#39;ajouter dans Réglages › Clés d&#39;API, type « Assistant IA ». »</li><li><strong>Ne jamais laisser inventer</strong> : quand la donnée n&#39;existe pas (module non activé, période sans vente), l&#39;outil le dit ; il ne renvoie ni zéro trompeur ni liste vide muette.</li></ol><p>Chaque outil porte un <strong>titre lisible</strong> et l&#39;annotation <strong>lecture seule</strong> (<code>readOnlyHint</code>) : l&#39;assistant peut alors l&#39;appeler sans redemander la permission à chaque fois, et c&#39;est exigé par l&#39;annuaire des connecteurs de Claude.</p><h2 id="_6-catalogue-d-outils-v1" tabindex="-1">6. Catalogue d&#39;outils (v1) <a class="header-anchor" href="#_6-catalogue-d-outils-v1" aria-label="Permalink to &quot;6. Catalogue d&#39;outils (v1)&quot;">​</a></h2><p>Paramètres communs : <code>store</code> (nom ou identifiant, facultatif), <code>period</code> ou <code>from</code> / <code>to</code>, <code>compare_to</code> (<code>previous_period</code> par défaut, <code>same_period_last_year</code>, <code>none</code>), <code>limit</code>. Résultat commun : <code>summary</code>, <code>period</code> (résolue, avec fuseau et libellé), <code>store</code>, les chiffres, <code>dataFreshAt</code>, <code>warnings</code>, <code>links</code> (back-office), <code>nextQuestions</code>. Résultat en texte <strong>et</strong> en contenu structuré avec schéma de sortie (<code>structuredContent</code>, <code>outputSchema</code>).</p><table tabindex="0"><thead><tr><th>Outil</th><th>Titre affiché</th><th>Données de l&#39;API publique</th></tr></thead><tbody><tr><td><code>list_stores</code></td><td>Mes magasins</td><td><code>GET /stores</code> (ceux que l&#39;accès autorise)</td></tr><tr><td><code>sales_summary</code></td><td>Bilan des ventes</td><td>rapports de ventes, tableau de bord, « En direct »</td></tr><tr><td><code>top_products</code></td><td>Produits qui marchent, produits dormants</td><td>rapports de ventes, stock dormant</td></tr><tr><td><code>margin_analysis</code></td><td>Marges et food cost</td><td>rapport des marges, historique des prix d&#39;achat, food cost</td></tr><tr><td><code>stock_status</code></td><td>État du stock</td><td>alertes de stock, valorisation, pertes, lots et dates limites</td></tr><tr><td><code>reorder_suggestions</code></td><td>Quoi commander</td><td>alertes de stock, rotation, bons de commande en cours</td></tr><tr><td><code>cash_control</code></td><td>Caisse et clôtures</td><td>sessions, rapports Z, validations manager</td></tr><tr><td><code>purchasing_status</code></td><td>Achats et fournisseurs</td><td>bons de commande, réceptions, échéances, soldes</td></tr><tr><td><code>devices_health</code></td><td>État des appareils</td><td>parc d&#39;appareils, signaux de santé</td></tr><tr><td><code>compare_stores</code></td><td>Comparer mes magasins</td><td>comparaison des magasins</td></tr><tr><td><code>find_product</code></td><td>Chercher un produit</td><td>catalogue, recherche</td></tr><tr><td><code>vendora_help</code></td><td>Aide Vendora</td><td>index du <a href="https://vendora-aide.onrender.com" target="_blank" rel="noreferrer">centre d&#39;aide</a> (FR / EN / AR)</td></tr><tr><td><code>fraud_alerts</code> (option)</td><td>Alertes anti-fraude</td><td>alertes, portée dédiée</td></tr></tbody></table><p>Noms techniques en anglais (stables, attendus par les annuaires), titres et réponses dans la langue du commerce — décision 5 ci-dessous. Quand un outil demande plusieurs appels (<code>reorder_suggestions</code>, <code>margin_analysis</code>), on ajoute une <strong>route d&#39;agrégation à l&#39;API publique</strong> plutôt que de multiplier les allers-retours : elle sert aussi le back-office et nos agents.</p><p><strong>Aide et liens directs (U4)</strong> :</p><ul><li><code>vendora_help</code> cherche dans <code>mcp-index.json</code>, index produit au build du centre d&#39;aide (une entrée par page : langue, titre, adresse, sections avec ancre et texte). Le serveur MCP le télécharge au démarrage puis toutes les 6 h depuis <code>VENDORA_HELP_URL</code> ; s&#39;il échoue ou si la version n&#39;est pas 1, il garde la dernière copie valide, et sans copie il renvoie l&#39;adresse de l&#39;aide. Recherche locale : mots normalisés (accents, casse, pluriels simples, quelques synonymes), titre &gt; intertitres &gt; texte, dans la langue de la question (FR / EN / AR). Il renvoie 2 ou 3 extraits avec titre et lien (ancre de section), balisés comme <strong>données</strong>. Sans page correspondante, il le dit, avec le lien de l&#39;accueil de l&#39;aide. Sa description demande au modèle de s&#39;en servir pour toute question « comment faire ».</li><li>Chaque lien vers le back-office ouvre l&#39;écran <strong>déjà filtré</strong> : <code>?store=&lt;id&gt;&amp;from=AAAA-MM-JJ&amp;to=AAAA-MM-JJ</code> (période résolue, dates dans le fuseau du magasin ; fuseau majoritaire pour « tous les magasins », comme le back-office), plus <code>tab=</code> pour les rapports de stock. Les écrans sans période reçoivent le magasin seulement. Toutes les adresses viennent de <code>VENDORA_BACKOFFICE_URL</code> et <code>VENDORA_HELP_URL</code>.</li></ul><p><strong>Prompts prêts</strong> (menu de l&#39;assistant) : « Bilan de ma journée », « Que commander cette semaine ? », « Pourquoi ma marge baisse ? », « Contrôle de caisse du soir », « Point hebdomadaire de mes magasins ».</p><h2 id="_7-architecture" tabindex="-1">7. Architecture <a class="header-anchor" href="#_7-architecture" aria-label="Permalink to &quot;7. Architecture&quot;">​</a></h2><ul><li><strong>Service séparé <code>mcp/</code></strong> dans le monorepo, <strong>client de l&#39;<a href="/VendoraSystem-docs/architecture/api-publique">API publique</a></strong> comme le back-office : jamais d&#39;accès direct à la base, jamais le rôle <code>pos_platform</code> ; les règles métier restent dans le serveur.</li><li><strong>HTTP distant d&#39;abord</strong> (<code>https://mcp.&lt;domaine&gt;/mcp</code>, transport « Streamable HTTP ») : c&#39;est ce que demandent claude.ai, les applications Claude (ordinateur, téléphone), Claude Code et ChatGPT. <strong>stdio</strong> reste possible pour un intégrateur, sans être le parcours du commerçant.</li><li><strong>Sans état, comme le protocole lui-même</strong> : la révision <strong>2026-07-28</strong> de MCP supprime les sessions et la poignée de main d&#39;initialisation ; chaque requête porte sa version et ses capacités, le serveur expose <code>server/discover</code>, chaque résultat porte <code>resultType</code>, les listes portent <code>ttlMs</code> / <code>cacheScope</code> et un ordre stable. Notre choix « sans état » du 08/11 est donc la norme. Le SDK doit aussi parler aux clients restés à la révision 2025-11-25.</li><li><strong>Deux façons de s&#39;authentifier</strong> : clé « Assistant IA » dans un en-tête (intégrateurs, M0 / M1) et <strong>OAuth 2.1</strong> (commerçants, M3). Jamais de jeton dans l&#39;URL.</li><li><strong>OAuth tel que Claude l&#39;attend</strong> (documentation des connecteurs, 11/11/2026) : réponse <strong>401</strong> avec <code>WWW-Authenticate: Bearer resource_metadata=&quot;…&quot;</code>, métadonnées de ressource protégée (RFC 9728) dont <code>resource</code> égale exactement l&#39;URL du serveur MCP, métadonnées du serveur d&#39;autorisation (RFC 8414), <strong>PKCE S256</strong>, identification du client par <strong>CIMD</strong> (Client ID Metadata Document — l&#39;enregistrement dynamique DCR est déprécié, gardé en repli), redirections <code>https://claude.ai/api/mcp/auth_callback</code> et boucle locale de Claude Code (<code>localhost</code> et <code>127.0.0.1</code>, port ignoré), rotation des jetons de renouvellement, paramètre <code>iss</code> (RFC 9207), points OAuth qui répondent en <strong>moins de 10 secondes</strong>.</li><li><strong>Ce qui est construit (M3, 11/11/2026)</strong> : le <strong>serveur Vendora est le serveur d&#39;autorisation</strong> (code maison, paquet <code>pos.server.oauth</code>), émetteur = adresse publique de l&#39;API ; le service <code>mcp/</code> reste sans état et sans secret — il annonce la connexion (401 + document de ressource protégée) et relaie le jeton à l&#39;API, qui décide. Un jeton d&#39;accès emprunte <strong>le chemin de code de la clé « Assistant IA »</strong> : il n&#39;existe pas de second contrôle d&#39;accès. Le consentement est une page du back-office. Règles : <a href="/VendoraSystem-docs/specs/18-mcp">spec 18</a> RG-MCP-30 à 48 ; routes : <a href="/VendoraSystem-docs/architecture/api-publique">API-PUBLIQUE.md</a> § 2.</li><li><strong>Constats du 11/11/2026 sur ce que les clients attendent</strong> (relus avant de coder ; à revérifier, ils bougent) : <ul><li><em>Claude</em> (documentation des connecteurs) : lit le <strong>401</strong> et son <code>resource_metadata</code> ; sonde <code>/.well-known/oauth-protected-resource/&lt;chemin&gt;</code> puis la racine ; exige que <code>resource</code> soit <strong>l&#39;adresse saisie, à l&#39;identique</strong> ; n&#39;utilise que la <strong>première</strong> entrée de <code>authorization_servers</code> ; choisit le document client (CIMD) si le serveur annonce <code>client_id_metadata_document_supported: true</code> et <code>none</code> dans <code>token_endpoint_auth_methods_supported</code>, sinon l&#39;enregistrement dynamique ; PKCE S256 ; redirection <code>https://claude.ai/api/mcp/auth_callback</code> ; renouvelle le jeton avant son expiration et sur un 401 ; laisse <strong>10 secondes</strong> à la découverte, à l&#39;enregistrement et au jeton.</li><li><em>Claude Code</em> : document client <code>https://claude.ai/oauth/claude-code-client-metadata</code>, redirections <code>http://localhost/callback</code> et <code>http://127.0.0.1/callback</code> (port variable). <strong>Vérifié en réel</strong> : notre serveur local a lu ce document (nom « Claude Code », domaine <code>claude.ai</code>, deux redirections) et le reconnaît comme vérifié.</li><li><em>Spécification MCP</em> : révision 2025-11-25 — ordre de préférence client pré-enregistré, puis CIMD, puis DCR ; révision 2026-07-28 — DCR déprécié, paramètre <code>iss</code> recommandé, <code>offline_access</code> jamais annoncé par la ressource.</li><li><em>ChatGPT</em> (guide des serveurs MCP personnalisés) : redirections <code>https://chatgpt.com/connector_platform_oauth_redirect</code> et <code>https://chatgpt.com/connector/oauth/{callback_id}</code>, document client <code>https://chatgpt.com/oauth/client.json</code>. <strong>Non vérifié en réel</strong> : aucun essai depuis ChatGPT.</li></ul></li><li><strong>Langage proposé : Kotlin</strong> (SDK MCP officiel, cohérent avec le futur service <code>agents/</code>) — alternative TypeScript (SDK le plus mûr, et le seul à fournir le paquet des cartes visuelles <code>@modelcontextprotocol/ext-apps</code>). À trancher.</li><li><strong>Cartes visuelles</strong> (lot U2) : extension officielle <strong>MCP Apps</strong> — un outil désigne une ressource <code>ui://…</code> (HTML) que l&#39;assistant affiche dans la conversation, dans un cadre isolé ; repli en texte partout ailleurs.</li></ul><h2 id="_8-lots" tabindex="-1">8. Lots <a class="header-anchor" href="#_8-lots" aria-label="Permalink to &quot;8. Lots&quot;">​</a></h2><h3 id="m0-—-prerequis-serveur-≈-1-semaine" tabindex="-1">M0 — Prérequis serveur (≈ 1 semaine) <a class="header-anchor" href="#m0-—-prerequis-serveur-≈-1-semaine" aria-label="Permalink to &quot;M0 — Prérequis serveur (≈ 1 semaine)&quot;">​</a></h3><p>Fait le 11/11/2026 (branche <code>mcp-m0</code>). Référence : <a href="/VendoraSystem-docs/architecture/api-publique">API-PUBLIQUE.md</a> §1, §3, §4, §6 ; spec 01 §6 ; spec 17 RG-PLAT-58 / 59.</p><ul><li>[x] Portées fines sur les clés d&#39;API : <strong>16 portées de lecture</strong> (<code>stores</code>, <code>catalog</code>, <code>sales</code>, <code>reports</code>, <code>inventory</code>, <code>purchases</code>, <code>devices</code>, <code>customers</code>, <code>fiscal</code>, <code>accounting</code>, <code>fraud</code>, <code>team</code>, <code>audit</code>, <code>settings</code>, <code>webhooks</code>, <code>account</code> — toutes en <code>:read</code>), READ / WRITE conservés à l&#39;identique. Classement route → portée <strong>fermé par défaut</strong> (<code>ApiKeyScopeRegistry</code>), un test échoue si une route publique de lecture n&#39;est pas classée. 403 <code>API_KEY_SCOPE</code> avec <code>requiredScope</code> et un message qui nomme la portée. <em>Pas fait : portées fines d&#39;écriture (hors lot, M4).</em></li><li>[x] Restriction d&#39;une clé (à portées fines) à un ou plusieurs magasins : 404 <code>STORE_NOT_ALLOWED</code> sur un autre magasin, listes et agrégats filtrés, routes du commerce entier refusées (403 <code>API_KEY_STORE_RESTRICTED</code>). Double barrière : contrôle de la route <strong>et</strong> politique PostgreSQL <code>store_scope</code>. Un test par contournement envisagé (agrégat, export, identifiant deviné, paramètre <code>storeId</code>).</li><li>[x] Type de clé « Assistant IA » (<code>kind = AGENT</code>) : lecture seule, préréglage <code>stores</code>, <code>catalog</code>, <code>sales</code>, <code>reports</code>, <code>inventory</code>, <code>purchases</code>, <code>devices</code> — <strong>sans <code>customers:read</code></strong> —, 120 requêtes par minute, expiration 90 jours par défaut (365 au plus).</li><li>[x] Acteur <code>AGENT</code> : journal <strong>dédié</strong> <code>agent_activity</code> (et non <code>audit_log</code>, réservé aux modifications), une ligne par clé, jour, lecture, magasin et période, avec compteur. Libellé lisible par code stable + paramètres, en français côté serveur et FR / EN / AR côté back-office. Route <code>GET /api/v1/agent-activity</code> prête pour la page du lot M2 (<strong>la page n&#39;est pas faite</strong>, comme prévu).</li><li>[x] Droit <code>MCP_ACCESS</code> dans les formules (console, actif dans toutes les formules existantes) ; arrêt d&#39;urgence par commerce (back-office, propriétaire) et global (console, ADMIN, motif obligatoire). Effet <strong>dès la requête suivante</strong>, sans cache (mesuré : refus 3 ms après la réponse de la bascule).</li><li>[x] Tests d&#39;intégration (<code>AgentAccessM0IntegrationTest</code>, <code>ApiKeyScopeRegistryTest</code>) ; <code>API-PUBLIQUE.md</code>, OpenAPI, specs 01, 13 et 17, centre d&#39;aide (page Clés d&#39;API, FR / EN / AR) à jour.</li></ul><p><strong>À savoir pour M1</strong> : la clé se présente par <code>Authorization: Bearer vd_live_…</code> ou <code>X-API-Key</code> ; <code>GET /api/v1/api-keys/me</code> donne ses portées et ses magasins (<code>storeIds</code>, <code>null</code> = tous) — à lire au démarrage pour n&#39;exposer que les outils utilisables. Les erreurs portent <code>error</code> (message relayable tel quel) et <code>code</code> ; <code>Retry-After</code> sur 429. Les routes d&#39;agrégation à ajouter en M1 doivent être <strong>classées</strong> dans <code>ApiKeyScopeRegistry</code> (sinon elles restent fermées et le test de classement échoue).</p><h3 id="m1-—-serveur-mcp-en-lecture-seule-≈-1-5-semaine" tabindex="-1">M1 — Serveur MCP en lecture seule (≈ 1,5 semaine) <a class="header-anchor" href="#m1-—-serveur-mcp-en-lecture-seule-≈-1-5-semaine" aria-label="Permalink to &quot;M1 — Serveur MCP en lecture seule (≈ 1,5 semaine)&quot;">​</a></h3><p>Fait le 11/11/2026 (branche <code>mcp-m1</code>). Référence : <a href="./../mcp/README"><code>mcp/README.md</code></a> (protocole, outils, routes, portées, variables, déploiement) ; preuves : <a href="/VendoraSystem-docs/captures/2026-11-11-mcp-m1/README"><code>docs/captures/2026-11-11-mcp-m1/</code></a>.</p><ul><li>[x] Service <code>mcp/</code> en Kotlin (JDK seul + kotlinx-serialization, aucun cadre), <strong>sans état</strong> : HTTP distant <code>POST /mcp</code>, <code>GET /healthz</code>, et stdio facultatif (<code>--stdio</code>). Clé « Assistant IA » relayée à chaque requête (<code>X-API-Key</code> ou <code>Authorization: Bearer</code>), jamais stockée ni journalisée. <strong>Lecture seule par construction</strong> : le client de l&#39;API ne sait faire que des <code>GET</code> (un test le vérifie). Image Docker (<code>mcp/Dockerfile</code>) construite et vérifiée en local.</li><li>[x] Révision <strong>2026-07-28</strong> (sans <code>initialize</code>, <code>server/discover</code>) et compatibilité 2025-11-25 / 2025-06-18 / 2025-03-26. <em>Le SDK officiel Kotlin 0.16.0 s&#39;arrête à 2025-11-25 : le protocole est écrit à la main (<code>Protocol.kt</code>).</em> Vérifié avec deux clients tiers : Claude Code 2.1.308 parle bien 2026-07-28 avec ce serveur, MCP Inspector 2.14.0 parle 2025-11-25. <strong>Réserve</strong> : pas de suite de conformité officielle 2026-07-28 ; les cas d&#39;erreur de cette révision ne sont couverts que par nos tests.</li><li>[x] <strong>13 outils</strong> (noms en anglais, titres en français) : <code>list_stores</code>, <code>sales_summary</code>, <code>top_products</code>, <code>margin_analysis</code>, <code>stock_status</code>, <code>reorder_suggestions</code>, <code>cash_control</code>, <code>purchasing_status</code>, <code>devices_health</code>, <code>compare_stores</code>, <code>find_product</code>, <code>vendora_help</code>, <code>fraud_alerts</code>. Titre, annotation lecture seule et sortie structurée (résumé, période réellement utilisée, fraîcheur, avertissements, liens, questions de suite) sur chacun. La liste dépend des portées de la clé ; <code>list_stores</code> dit ce que l&#39;accès n&#39;inclut pas.</li><li>[x] Routes d&#39;agrégation de l&#39;API publique pour le réassort et l&#39;analyse de marge (classées dans <code>ApiKeyScopeRegistry</code>, documentées dans <code>API-PUBLIQUE.md</code> et l&#39;OpenAPI).</li><li>[x] 5 prompts prêts (<code>daily_review</code>, <code>weekly_order</code>, <code>margin_drop</code>, <code>evening_cash_check</code>, <code>weekly_stores_review</code>) ; textes libres balisés comme données dans les consignes, les descriptions et chaque réponse (<code>dataNotice</code>).</li><li>[x] Tests : 39 tests du module contre un faux serveur Vendora (périodes, formats, protocole, outils, bout en bout), MCP Inspector, <strong>preuve réelle</strong> avec Claude Code sur un serveur de dev et le commerce de démo ; premier passage du jeu de questions (U1, ci-dessous).</li></ul><p><strong>Restes de M1</strong> (non faits, à reprendre) :</p><ul><li><strong>Rien n&#39;est déployé.</strong> Le service est prêt pour Render (étapes dans <code>mcp/README.md</code>) mais <code>render.yaml</code> n&#39;est pas modifié : c&#39;est le lot M2.</li><li><strong>Titres et réponses en français seulement</strong> : l&#39;API publique n&#39;expose pas la langue du commerce. La décision « titres dans la langue du commerce » n&#39;est donc tenue que pour un commerce francophone ; il faut exposer la langue (par exemple dans <code>GET /api/v1/api-keys/me</code>) puis traduire titres, résumés et avertissements (EN, AR).</li><li>Les messages du serveur renvoient à <strong>Réglages › Clés d&#39;API, type « Assistant IA »</strong>, seul endroit où la clé se règle aujourd&#39;hui (corrigé le 11/11 : ils citaient une page « Réglages › Assistant IA » qui n&#39;existe pas avant M2). À reprendre quand cette page existera (constante <code>KEY_SETTINGS</code>, <code>Context.kt</code>).</li><li>MCP Inspector signale des avertissements de portabilité sur les schémas de sortie (types <code>[&quot;object&quot;,&quot;null&quot;]</code>) : non traités, sans effet constaté sur Claude Code.</li><li>Pas de cartes visuelles (U2), pas de limite de débit propre au serveur MCP (celle de l&#39;API, 120 requêtes par minute et par clé, s&#39;applique : un bilan multi-magasins consomme plusieurs requêtes).</li><li>Claude Code ne transmet au modèle que le contenu structuré d&#39;une réponse d&#39;outil, pas son texte : tout ce que le modèle doit lire est donc dans le contenu structuré. À revérifier avec chaque nouveau client (Claude, ChatGPT).</li></ul><p><strong>À savoir pour M3</strong> : sans clé, <code>tools/list</code> et <code>tools/call</code> répondent 401 avec <code>WWW-Authenticate: Bearer realm=&quot;vendora-mcp&quot;</code> — c&#39;est là que se branche la découverte OAuth (<code>resource_metadata</code>). Le serveur MCP ne valide rien lui-même : il relaie l&#39;en-tête <code>Authorization: Bearer …</code> tel quel à l&#39;API Vendora et lit <code>GET /api/v1/api-keys/me</code> (portées, <code>storeIds</code>) à chaque requête. Un jeton OAuth doit donc être accepté par l&#39;API Vendora sur les mêmes routes, et une route équivalente à <code>api-keys/me</code> doit répondre pour un jeton. <code>server/discover</code>, <code>initialize</code>, <code>ping</code> et les prompts répondent sans authentification.</p><h3 id="m3-—-connexion-oauth-2-1-≈-1-5-semaine-—-recommande-avant-m2" tabindex="-1">M3 — Connexion OAuth 2.1 (≈ 1,5 semaine) — <strong>recommandé avant M2</strong> <a class="header-anchor" href="#m3-—-connexion-oauth-2-1-≈-1-5-semaine-—-recommande-avant-m2" aria-label="Permalink to &quot;M3 — Connexion OAuth 2.1 (≈ 1,5 semaine) — **recommandé avant M2**&quot;">​</a></h3><p>Fait le 11/11/2026 (branche <code>mcp-m3</code>), <strong>prouvé en local seulement</strong>. Référence : <a href="/VendoraSystem-docs/specs/18-mcp">spec 18</a> RG-MCP-30 à 48 ; <a href="/VendoraSystem-docs/architecture/api-publique">API-PUBLIQUE.md</a> § 2 ; fiche <a href="./lots/mcp-m3"><code>docs/lots/mcp-m3.md</code></a> ; preuves : <a href="/VendoraSystem-docs/captures/2026-11-11-mcp-m3/README"><code>docs/captures/2026-11-11-mcp-m3/</code></a>.</p><ul><li>[x] Serveur d&#39;autorisation sur le serveur Vendora (comptes du back-office), conforme au § 7 : métadonnées (RFC 8414), <code>/oauth/token</code>, <code>/oauth/revoke</code> (RFC 7009), <code>/oauth/register</code> (DCR, repli), point d&#39;autorisation sur l&#39;origine du back-office (<code>/api/v1/oauth/authorize</code>) ; code d&#39;autorisation + <strong>PKCE S256 obligatoire</strong>, <code>resource</code> (RFC 8707), <code>iss</code> (RFC 9207), <code>state</code>, code de 60 secondes à usage unique ; client par <strong>document client (CIMD)</strong> lu avec protection contre les requêtes vers l&#39;intérieur, redirections en correspondance exacte (port ignoré en boucle locale), jamais de redirection vers une adresse non validée. <strong>Code maison</strong> plutôt que Spring Authorization Server : les jetons devaient emprunter le chemin des clés « Assistant IA » (filtre, RLS, magasins, journal) et le consentement vivre dans le back-office Angular — la bibliothèque aurait imposé ses propres jetons, ses tables et sa page.</li><li>[x] Écran de consentement FR / EN / AR en langage simple (<code>/connecter-assistant</code>) : quel assistant (nom, domaine, vérifié ou non), quels magasins, quelles familles de données, lecture seule, phrase « ces données sont envoyées à l&#39;assistant que vous avez choisi » ; Autoriser / Refuser ; clair et sombre, téléphone et bureau. Page du centre d&#39;aide « Connecter un assistant IA en un clic » (FR / EN / AR).</li><li>[x] Jetons opaques hachés (<code>vd_oat_…</code> 1 h, <code>vd_ort_…</code> 90 jours tournant, rejeu → connexion révoquée), liés à l&#39;utilisateur, aux magasins, aux portées et au client ; <strong>mêmes règles que les clés</strong> (lecture seule, portées, magasins, journal <code>agent_activity</code>, arrêts d&#39;urgence, <code>MCP_ACCESS</code>, 120 requêtes par minute) ; accès recalculé à chaque requête ; <strong>révocation au back-office</strong> : section « Assistants connectés » de Réglages › Clés d&#39;API.</li><li>[x] Côté <code>mcp/</code> : 401 avec <code>resource_metadata</code>, document de ressource protégée (racine et <code>/mcp</code>), jeton relayé, 401 <code>invalid_token</code> sur un jeton expiré ou retiré, 403 sur un arrêt d&#39;urgence.</li><li>[x] Tests : 39 tests serveur (<code>OAuthM3IntegrationTest</code> 28, <code>OAuthRulesTest</code> 11) et le garde-fou de démarrage (<code>EnvironmentGuardTest</code>), 5 tests <code>mcp/</code> (<code>OAuthDiscoveryTest</code>), tests web de la page de consentement et de la section ; <strong>preuve de bout en bout en local</strong> par <code>mcp/tools/oauth-e2e.py</code> (client OAuth complet contre les trois services : 71 vérifications sur 71).</li><li>[x] <strong>Relecture de sécurité du 12/11/2026 appliquée</strong> (détail et tests dans la fiche de lot) : date limite ferme et plafond de lectures du document client, stockage borné et ménage, plus de redirection ouverte pour un client non vérifié, demande liée au navigateur (cookie posé par le point d&#39;autorisation, sur l&#39;origine du back-office), noms d&#39;assistants réservés, audit complet (refus, révocation par le client, rejeu), interrupteur <code>POS_OAUTH_ENABLED</code> (éteint par défaut), plafond de débit global, échange du code atomique, paramètres en double refusés, « Vérifié » sur l&#39;identifiant client exact, CORS.</li><li>[ ] Preuve réelle : connecteur ajouté dans Claude sur le staging, depuis un téléphone. <strong>À faire par Ahmed</strong> après déploiement et pose des variables (pas-à-pas dans le README des captures ; variables dans <code>deploy/README.md</code> § 8).</li></ul><p><strong>Restes de M3</strong> (non faits, à reprendre) :</p><ul><li><strong>Aucun essai avec un vrai client</strong> : ni claude.ai, ni l&#39;application téléphone, ni ChatGPT, ni Claude Code en conditions réelles (l&#39;essai Claude Code demande un humain devant le navigateur ; seul son document client a été lu en réel). Les exigences sont tenues d&#39;après la documentation, pas d&#39;après un essai.</li><li><strong>Hébergement</strong> : le plan gratuit met les services en veille ; leur réveil dépasse les 10 secondes laissées par Claude. Il faut réveiller l&#39;API et le MCP avant de connecter (ou un plan sans veille : lot M2).</li><li><strong>Hameçonnage</strong> : un lien de <strong>consentement</strong> transmis à un commerçant ne mène plus à rien (demande liée au navigateur qui l&#39;a ouverte). Reste possible : envoyer un lien d&#39;<strong>autorisation</strong> forgé, qui ouvre une demande dans le navigateur du commerçant. Parades en place : « Non vérifié », domaine de retour affiché, nom d&#39;assistant connu remplacé par le domaine, lecture seule, rien de coché pour l&#39;anti-fraude. Non fait : n&#39;accepter que des clients vérifiés, DCR désactivable par configuration.</li><li><strong>Relais du staging</strong> : le cookie de liaison traverse la règle <code>/api/*</code> du back-office ; prouvé avec le proxy de développement seulement, à vérifier une fois sur Render (<code>deploy/README.md</code> § 8).</li><li><code>resource</code> est vérifié à l&#39;émission du jeton, pas relu à chaque usage (une seule ressource aujourd&#39;hui).</li><li><strong>Rejeu strict</strong> : pas de fenêtre de grâce sur le renouvellement — un client qui perd la réponse doit reconnecter. À assouplir seulement si un vrai client le provoque.</li><li>À la rotation, l&#39;ancien jeton d&#39;accès reste valable jusqu&#39;à son heure d&#39;expiration (une heure au plus).</li><li>La limite de débit des points OAuth est par adresse appelante <strong>et</strong> globale : derrière un proxy, vérifier dans le journal de l&#39;API (une ligne au premier appel) que l&#39;adresse vue est bien celle du client.</li><li>Pas d&#39;introspection ; pas de purge planifiée (les lignes expirées sont purgées au fil des demandes, au plus une fois par minute).</li><li>Messages d&#39;erreur des points OAuth en français seulement.</li></ul><h3 id="m2-—-page-«-assistant-ia-»-tutoriel-hebergement-≈-1-semaine" tabindex="-1">M2 — Page « Assistant IA », tutoriel, hébergement (≈ 1 semaine) <a class="header-anchor" href="#m2-—-page-«-assistant-ia-»-tutoriel-hebergement-≈-1-semaine" aria-label="Permalink to &quot;M2 — Page « Assistant IA », tutoriel, hébergement (≈ 1 semaine)&quot;">​</a></h3><ul><li>[x] <em>(12/11)</em> Back-office › Réglages › <strong>Assistant IA</strong> : « Connecter Claude », « Connecter ChatGPT » (adresse à copier, QR pour le téléphone, étapes illustrées), bouton <strong>Tester la connexion</strong>, assistants connectés, clés pour intégrateurs, <strong>activité lisible</strong>, retrait d&#39;un accès, arrêt d&#39;urgence, questions pour bien commencer.</li><li>[x] <em>(12/11, parcours H8-18)</em> Centre d&#39;aide : « Brancher votre assistant IA » à partir du <a href="/VendoraSystem-docs/architecture/mcp-guide">guide</a>, FR / EN / AR.</li><li>[ ] <em>(reporté à l&#39;hébergement de production, décision du 12/11 : la veille du staging est acceptée et signalée sur la page)</em> Hébergement de staging <code>vendora-mcp-staging</code> — <strong>sans mise en veille</strong> : un service qui dort ne tient pas les 10 secondes laissées aux points OAuth.</li><li>[x] <em>(12/11, RG-MCP-49 → 54)</em> Spec <strong>18-mcp</strong> : créée au lot M3 (<a href="/VendoraSystem-docs/specs/18-mcp">specs/18-mcp.md</a>, M0 / M1 / M3) — à compléter avec la page ; site (fonctionnalités, vitrine), README.</li></ul><h3 id="experience-u1-→-u6" tabindex="-1">Expérience (U1 → U6) <a class="header-anchor" href="#experience-u1-→-u6" aria-label="Permalink to &quot;Expérience (U1 → U6)&quot;">​</a></h3><ul><li>[x] <strong>U1 — Jeu de questions de référence</strong> — fait le 11/11/2026 (<a href="./../mcp/evals/README"><code>mcp/evals/</code></a>) : 53 questions (restaurant 22, épicerie 12, multi-magasins 10, boulangerie 6, boutique 3 ; 47 FR, 3 EN, 3 AR) avec outil, période et chiffres attendus, sur un jeu de données déterministe à trois magasins et une horloge figée ; lanceur en une commande (<code>run.py</code>) qui note bon outil, bonne période, chiffre exact, aucun chiffre inventé, fraîcheur répétée, et <strong>l&#39;efficacité du chemin</strong> (premier outil appelé = outil attendu, appels par question, appels en erreur — seuils 90 %, 1,15 et 5 %) ; journal des questions sans réponse par catégorie. <strong>Jeu complet repassé après correctifs (Claude Code sans interface, modèle <code>claude-sonnet-5-5</code>) : 52/53, soit 98,1 %, premier outil juste 98 %, 1,04 appel par question</strong> ; le raté (r14, alertes anti-fraude reconstituées avec le contrôle de caisse) est un vrai défaut de consignes, corrigé et repris (6/6 avec cinq témoins) — le jeu complet n&#39;a pas été repassé une troisième fois. Le passage précédent du même jour (51/53, premier outil juste 82 %, 1,25 appel) avait révélé un détour par <code>list_stores</code> avant une question sur sept : description et consignes corrigées. Défaut du serveur trouvé en chemin : la répartition par moyen de paiement comptait la monnaie rendue dans les espèces. <strong>Régression volontaire détectée</strong> (13 descriptions réduites à « Outil Vendora. », descriptions de paramètres et consignes retirées, mêmes 53 questions) : premier outil juste 98 % → 65 %, appels par question 1,04 → 1,81, appels en erreur 1 → 9 (dont 4 dus au quota de débit), score 52/53 → 49/53 (50/53 hors quota). <strong>La justesse seule ne franchit pas le seuil de 90 % : ce sont les seuils d&#39;efficacité qui font échouer le passage.</strong> Retirer les avertissements du contenu structuré n&#39;est pas détecté (9/9) : le modèle retrouve la fraîcheur dans le champ <code>dataFreshAt</code>. <em>Restes : le moteur « API Claude » est écrit mais n&#39;a jamais tourné (pas de clé) ; un seul modèle, variance d&#39;un passage à l&#39;autre non mesurée (les seuils d&#39;efficacité reposent sur deux passages) ; pas de magasin « boutique » dans le jeu de données ; un magasin désigné par son métier dans une autre langue (« the bakery ») coûte un appel refusé ; « ce qui risque de manquer » passe encore par <code>stock_status</code> avant <code>reorder_suggestions</code> ; le correcteur reconnaît les refus par une liste de formulations, à relire en cas de raté ; un passage dégradé fait plus d&#39;appels et peut buter sur le quota de 120 requêtes par minute et par clé.</em></li><li>[ ] <strong>U2 — Cartes visuelles dans la conversation</strong> (≈ 1 semaine) : bilan du jour, réassort, comparaison des magasins en MCP Apps, repli en texte.</li><li>[ ] <strong>U3 — Bibliothèque de questions et routines par métier</strong> (≈ 3 jours) : restaurant, boulangerie, épicerie, boutique ; prompts, page d&#39;aide, exemples au back-office, bilans programmés.</li><li>[ ] <strong>U4 — Aide Vendora et liens directs</strong> (≈ 3 jours) : outil <code>vendora_help</code>, liens vers l&#39;écran du back-office dans chaque réponse.</li><li>[ ] <strong>U5 — Commerce de démonstration public</strong> (≈ 3 jours) : serveur de démo sans compte, données fictives, bouton « Essayer avec Claude » sur la vitrine. <em>Fait les 11 et 12/11 : semis, ajout nocturne, chemin <code>/demo/mcp</code> (RG-MCP-55 → 58). Reste : activation sur le staging et bloc de la vitrine, après la décision d&#39;hébergement.</em></li><li>[ ] <strong>U6 — Annuaires Claude et ChatGPT</strong> (≈ 4 jours + délai de revue) : fiche, politique de confidentialité, documentation publique, compte de test, captures.</li></ul><h3 id="m4-—-ecriture-encadree-apres-le-lot-gaas-a2" tabindex="-1">M4 — Écriture encadrée (après le lot GaaS A2) <a class="header-anchor" href="#m4-—-ecriture-encadree-apres-le-lot-gaas-a2" aria-label="Permalink to &quot;M4 — Écriture encadrée (après le lot GaaS A2)&quot;">​</a></h3><ul><li>[ ] Aucune écriture directe : les outils d&#39;écriture <strong>créent des propositions</strong> (<code>agent_proposals</code>) — bon de commande brouillon, changement de prix, acquittement d&#39;alerte — validées par le gérant (back-office, app, PIN manager). Annotations d&#39;écriture sur ces outils ; l&#39;assistant redemande alors la permission.</li></ul><h2 id="_9-garde-fous-des-m1" tabindex="-1">9. Garde-fous (dès M1) <a class="header-anchor" href="#_9-garde-fous-des-m1" aria-label="Permalink to &quot;9. Garde-fous (dès M1)&quot;">​</a></h2><ul><li><strong>Lecture seule</strong> tant que M4 n&#39;existe pas ; paiement, fiscal en écriture, PIN, clés et délégations hors d&#39;atteinte (comme l&#39;API publique).</li><li><strong>Données personnelles</strong> : clients et salariés en agrégats ou pseudonymisés ; noms et coordonnées seulement avec la portée <code>customers:read</code>, décochée par défaut et expliquée à l&#39;écran de consentement.</li><li><strong>Injection de consignes</strong> : noms de produits, notes fournisseurs, messages de clients sont des <strong>données</strong>, jamais des instructions ; les réponses des outils les balisent comme telles.</li><li><strong>Le commerçant choisit où vont ses données</strong> : Vendora ne les transmet qu&#39;à l&#39;assistant qu&#39;il a lui-même connecté ; l&#39;écran de consentement et le guide le disent, avec un renvoi aux conditions de l&#39;assistant.</li><li>Débit limité par accès, audit de chaque appel, révocation immédiate, vérification de l&#39;en-tête <code>Origin</code>.</li><li><strong>Accès selon l&#39;abonnement</strong> (lot ME6, spec 17 RG-PLAT-58 / 80 → 82) : option « Assistant IA » des formules payantes (3 mois offerts, puis 7 € / 15 DT par mois), incluse dans Sur mesure, absente de Gratuit ; option retirée → clés et connexions suspendues (402 <code>AGENT_ACCESS_NOT_IN_PLAN</code>, « Activez l&#39;option Assistant IA »), rien supprimé, reprise au nouvel ajout.</li></ul><h2 id="_10-mesures-de-succes" tabindex="-1">10. Mesures de succès <a class="header-anchor" href="#_10-mesures-de-succes" aria-label="Permalink to &quot;10. Mesures de succès&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mesure</th><th>Cible</th></tr></thead><tbody><tr><td>Temps entre « Connecter » et la première réponse</td><td>moins de 2 minutes (médiane)</td></tr><tr><td>Questions de référence correctes (bon outil, bon chiffre, bonne période)</td><td>90 % au moins, <strong>aucun chiffre inventé</strong></td></tr><tr><td>Temps de réponse d&#39;un outil</td><td>moins de 2 secondes (95e centile)</td></tr><tr><td>Commerces avec un assistant connecté 30 jours après l&#39;ouverture</td><td>à suivre (console)</td></tr><tr><td>Commerces qui posent au moins une question par semaine</td><td>à suivre</td></tr><tr><td>Questions sans réponse les plus fréquentes</td><td>revues chaque mois, alimentent les outils</td></tr></tbody></table><h2 id="_11-effort-et-ordre-recommande" tabindex="-1">11. Effort et ordre recommandé <a class="header-anchor" href="#_11-effort-et-ordre-recommande" aria-label="Permalink to &quot;11. Effort et ordre recommandé&quot;">​</a></h2><p><code>M0 → M1 (+ U1) → M3 → M2 (+ U3, U4) → U5 → U2 → U6 → M4</code></p><ul><li><strong>Utilisable par un intégrateur</strong> (clé, Claude Code) : M0 + M1 ≈ 2,5 semaines.</li><li><strong>Utilisable par un commerçant seul, sur son téléphone</strong> : + M3 + M2 ≈ 5 semaines au total.</li><li>Expérience complète (U1 → U6) : ≈ 3,5 semaines de plus, par petits lots indépendants. M4 avec la suite GaaS.</li></ul><h2 id="_12-decisions-a-prendre-avant-de-demarrer" tabindex="-1">12. Décisions à prendre avant de démarrer <a class="header-anchor" href="#_12-decisions-a-prendre-avant-de-demarrer" aria-label="Permalink to &quot;12. Décisions à prendre avant de démarrer&quot;">​</a></h2><ol><li><strong>Langage</strong> : Kotlin (recommandé pour la cohérence) ou TypeScript (recommandé si les cartes visuelles U2 passent en priorité).</li><li><strong>Ordre</strong> : OAuth (M3) <strong>avant</strong> la page du back-office (nouvelle recommandation), ou clé à copier d&#39;abord (plan du 08/11). Raison du changement : sur claude.ai et ses applications, la clé dans un en-tête est en bêta et réservée au propriétaire d&#39;une organisation ; un commerçant sur son téléphone ne peut se connecter que par OAuth.</li><li><strong>Données clients</strong> : exclues de la v1 (recommandé) ou accessibles avec une portée explicite.</li><li><strong>Commercial</strong> : inclus dans toutes les formules (lecture seule) ou réservé à une formule / un add-on.</li><li><strong>Langue des outils</strong> : noms techniques en anglais et titres dans la langue du commerce (recommandé), ou tout en français.</li><li><strong>Domaine</strong> du serveur (<code>mcp.…</code>) et hébergement de production — l&#39;adresse ne doit plus changer une fois les commerçants connectés.</li></ol><h2 id="_13-ce-qui-change-par-rapport-au-plan-du-08-11" tabindex="-1">13. Ce qui change par rapport au plan du 08/11 <a class="header-anchor" href="#_13-ce-qui-change-par-rapport-au-plan-du-08-11" aria-label="Permalink to &quot;13. Ce qui change par rapport au plan du 08/11&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sujet</th><th>Plan du 08/11</th><th>Besoin révisé du 11/11</th></tr></thead><tbody><tr><td>Point de départ</td><td>Exposer l&#39;API en outils</td><td>Les questions du commerçant, par métier</td></tr><tr><td>Connexion</td><td>Clé à copier d&#39;abord, OAuth « peut attendre »</td><td>OAuth avant la page ; la clé pour les intégrateurs</td></tr><tr><td>Transport</td><td>stdio et HTTP à égalité</td><td>HTTP distant d&#39;abord, stdio en option</td></tr><tr><td>Outils</td><td>Une douzaine, calqués sur les rapports</td><td>Par question, périodes en mots, comparaison incluse, erreurs utiles, liens</td></tr><tr><td>Réponses</td><td>Texte et montants formatés</td><td>+ contenu structuré, questions de suite, cartes visuelles (U2)</td></tr><tr><td>Qualité</td><td>Tests par outil</td><td>+ jeu de questions de référence rejoué à chaque changement (U1)</td></tr><tr><td>Découverte</td><td>Tutoriel</td><td>+ commerce de démo public (U5), annuaires (U6), bibliothèque de questions (U3)</td></tr><tr><td>Protocole</td><td>« Sans état » comme choix</td><td>Révision 2026-07-28 : sans état par construction, CIMD, annotations</td></tr></tbody></table><h2 id="_14-sources-consultees-le-11-11-2026" tabindex="-1">14. Sources (consultées le 11/11/2026) <a class="header-anchor" href="#_14-sources-consultees-le-11-11-2026" aria-label="Permalink to &quot;14. Sources (consultées le 11/11/2026)&quot;">​</a></h2><ul><li>Protocole MCP, changements de la révision 2026-07-28 : &lt;<a href="https://modelcontextprotocol.io/specification/2026-07-28/changelog" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2026-07-28/changelog</a>&gt;</li><li>Connecteurs Claude — authentification : &lt;<a href="https://claude.com/docs/connectors/building/authentication" target="_blank" rel="noreferrer">https://claude.com/docs/connectors/building/authentication</a>&gt;</li><li>Protocole MCP — autorisation, révisions 2025-11-25 et 2026-07-28 : &lt;<a href="https://modelcontextprotocol.io/specification/2025-11-25/basic/authorization" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2025-11-25/basic/authorization</a>&gt; et &lt;<a href="https://modelcontextprotocol.io/specification/2026-07-28/basic/authorization" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2026-07-28/basic/authorization</a>&gt;</li><li>OAuth Client ID Metadata Document (brouillon IETF) : &lt;<a href="https://datatracker.ietf.org/doc/draft-ietf-oauth-client-id-metadata-document/" target="_blank" rel="noreferrer">https://datatracker.ietf.org/doc/draft-ietf-oauth-client-id-metadata-document/</a>&gt;</li><li>Normes appliquées au lot M3 : OAuth 2.1 (brouillon), RFC 7636 (PKCE), 8414 (métadonnées), 9728 (ressource protégée), 8707 (<code>resource</code>), 9207 (<code>iss</code>), 7009 (révocation), 7591 (enregistrement dynamique), 8252 (applications installées), 6750 (jetons porteurs)</li><li>Connecteurs Claude — soumission à l&#39;annuaire : &lt;<a href="https://claude.com/docs/connectors/building/submission" target="_blank" rel="noreferrer">https://claude.com/docs/connectors/building/submission</a>&gt;</li><li>Connecteurs Claude — ajouter un connecteur personnalisé : &lt;<a href="https://claude.com/docs/connectors/custom/add-unlisted.md" target="_blank" rel="noreferrer">https://claude.com/docs/connectors/custom/add-unlisted.md</a>&gt;</li><li>MCP Apps (cartes visuelles) : &lt;<a href="https://blog.modelcontextprotocol.io/posts/2026-01-26-mcp-apps/" target="_blank" rel="noreferrer">https://blog.modelcontextprotocol.io/posts/2026-01-26-mcp-apps/</a>&gt;</li><li>ChatGPT — serveurs MCP personnalisés : &lt;<a href="https://help.openai.com/articles/12584461" target="_blank" rel="noreferrer">https://help.openai.com/articles/12584461</a>&gt; et &lt;<a href="https://developers.openai.com/api/docs/guides/custom-mcp-server.md" target="_blank" rel="noreferrer">https://developers.openai.com/api/docs/guides/custom-mcp-server.md</a>&gt; (disponibilité selon les formules : à revérifier au démarrage du lot M3)</li></ul></div>',1)])])}const g=t(a,[["render",n]]);export{m as __pageData,g as default};
